window.MG_LAZY_DATA["data/lazy/courses/a042-b2ecf83d7af74667.json"]={sha256:"b2ecf83d7af746671d8bc8341fe86f1d30298d0f6dabbf1924f0cc112ae5ead4",value:{"id":"a042","title":"高數值孔徑 EUV 成像","titleEn":"High-numerical-aperture EUV imaging","category":"semiconductor","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"stepCount":24,"estimatedMinutes":720,"languageCoverage":["zh-TW","en"],"sourceIds":["v7-highna-asml","v7-highna-rayleigh","v7-highna-optics","v7-highna-lab","v7-highna-ecosystem","v7-highna-process","v7-highna-metrology","v7-highna-motion","v3-media-bc42a1134319"],"simulationOnly":true,"summary":"從解析度、非等倍率光學、光罩與薄光阻，到接縫、焦距控制及缺陷量測，完成 High-NA EUV 成像整合審查。","summaryEn":"Review High-NA EUV imaging from resolution and anamorphic optics through masks, thin resist, field stitching, focus control and defect metrology.","scope":"依公開原理編寫的四階段、24 個教學工作包；每步需交出模型、判讀或驗證紀錄。數值練習為自訂教學案例，不是廠商製程配方、現場操作許可或專業設計認證。","scopeEn":"Four stages and 24 educational work packages based on public principles. Each step produces a model, interpretation or verification record. Numerical exercises are hypothetical, not manufacturer recipes, field operating authorization or professional design certification.","diagram":{"type":"lithography","labels":["光源","反射光罩","非等倍率反射鏡","光阻","量測"],"labelsEn":["Source","Reflective mask","Anamorphic mirrors","Resist","Metrology"],"original":true,"notToScale":true},"stages":[{"id":"a042-stage01","order":1,"title":"成像與光學預算","titleEn":"Imaging and optical budgets","description":"比較解析度、焦深、反射光路與非等倍率。","descriptionEn":"Compare resolution, depth of focus, reflective paths and anamorphic scaling.","steps":[{"id":"a042-v7-01","order":1,"sequence":1,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-asml","v7-highna-rayleigh"],"prerequisiteIds":[],"title":"分開節點名稱與實際線寬","titleEn":"Separate node labels from feature dimensions","objective":"建立不混淆的尺度表。","objectiveEn":"Build an unambiguous scale table.","instruction":"列出節點名稱、線寬、節距與波長四欄；畫兩條線標出線寬與節距；把公開光學解析度放在正確欄位；標記未公開的元件尺寸。","instructionEn":"List node label, linewidth, pitch and wavelength; draw two lines with width and pitch; place published optical resolution in its proper column; mark unpublished device dimensions.","observation":"節點名稱不能直接代入每個幾何尺寸。","observationEn":"A node label is not every physical dimension.","failure":"若把「2 nm」當成所有線寬，退回欄位定義。","failureEn":"Revisit definitions if a 2 nm label is treated as every linewidth.","check":"示意圖清楚區分至少三種尺度。","checkEn":"The diagram clearly distinguishes at least three scales.","knowledge":[{"id":"a042-v7-01-k1","title":"原理與限制","titleEn":"Principle and limits","text":"微影解析度與半導體節點命名描述不同層面。","textEn":"Lithographic resolution and node naming describe different aspects."},{"id":"a042-v7-01-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"節距包含線與間距，不能只報線寬。","textEn":"Pitch includes a line and space; linewidth alone is insufficient."}],"quiz":{"question":"節點名稱能直接代表所有線寬嗎？","questionEn":"Does a node name directly specify all linewidths?","options":["不能，需使用各層實際尺寸定義。","可以，每一條線都等於節點數字。","可以，節距與波長也相同。"],"optionsEn":["No; use layer-specific dimensions.","Yes; every line equals the node number.","Yes; pitch and wavelength are identical too."],"answer":0,"explanation":"不能，需使用各層實際尺寸定義。 微影解析度與半導體節點命名描述不同層面。","explanationEn":"No; use layer-specific dimensions. Lithographic resolution and node naming describe different aspects."}},{"id":"a042-v7-02","order":2,"sequence":2,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-rayleigh"],"prerequisiteIds":["a042-v7-01"],"title":"用 Rayleigh 關係比較 NA","titleEn":"Compare numerical aperture with Rayleigh scaling","objective":"在固定條件下判斷解析度趨勢。","objectiveEn":"Assess resolution trends under fixed conditions.","instruction":"寫出 R=k1×λ/NA；固定 k1 與波長；比較 NA 0.33 與 0.55 的比值；列出不能保持固定時需重新建模的項目。","instructionEn":"Write R=k1×wavelength/NA; hold k1 and wavelength fixed; compare NA 0.33 and 0.55; list what must be remodeled if assumptions change.","observation":"NA 增大使理想化可解析尺寸減小。","observationEn":"Higher NA reduces the idealized resolvable size.","failure":"不把此比例直接當成晶片效能倍數。","failureEn":"Do not convert this ratio directly into a chip-performance multiplier.","check":"計算含無因次比值及固定條件。","checkEn":"Provide the dimensionless ratio and held conditions.","knowledge":[{"id":"a042-v7-02-k1","title":"原理與限制","titleEn":"Principle and limits","text":"Rayleigh 關係提供光學解析度的尺度估算。","textEn":"The Rayleigh relationship estimates resolution scaling."},{"id":"a042-v7-02-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"k1 代表製程與成像因素，不是永遠相同的常數。","textEn":"k1 captures imaging and process factors and need not stay constant."}],"quiz":{"question":"固定 λ 與 k1 時，提高 NA 如何影響 R？","questionEn":"At fixed wavelength and k1, what does higher NA do to R?","options":["使 R 同比例變大。","使 R 變小。","完全沒有影響。"],"optionsEn":["It increases R proportionally.","It decreases R.","It has no effect."],"answer":1,"explanation":"使 R 變小。 Rayleigh 關係提供光學解析度的尺度估算。","explanationEn":"It decreases R. The Rayleigh relationship estimates resolution scaling."}},{"id":"a042-v7-03","order":3,"sequence":3,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-process"],"prerequisiteIds":["a042-v7-02"],"title":"建立焦深取捨","titleEn":"Build the depth-of-focus tradeoff","objective":"比較横向解析度與垂直容忍度。","objectiveEn":"Compare lateral resolution with vertical tolerance.","instruction":"以 DOF 與 λ/NA² 的比例畫趨勢；比較兩種 NA；把晶圓高度誤差放入焦深帶；標記離焦風險區。","instructionEn":"Plot the DOF proportionality to wavelength/NA squared; compare two NAs; place wafer-height errors inside the focus band; mark defocus-risk regions.","observation":"更細的成像通常伴隨更小的高度容忍度。","observationEn":"Finer imaging generally comes with tighter height tolerance.","failure":"若只看解析度，補上焦深及表面高度誤差預算。","failureEn":"Add focus depth and height-error budgets to resolution-only analysis.","check":"一圖同時顯示解析度收益與焦深代價。","checkEn":"One figure shows both resolution benefit and focus-depth cost.","knowledge":[{"id":"a042-v7-03-k1","title":"原理與限制","titleEn":"Principle and limits","text":"固定其他因素時，焦深對 NA 的平方敏感。","textEn":"With other factors fixed, focus depth scales inversely with NA squared."},{"id":"a042-v7-03-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"真實製程視窗仍受光阻、圖案及量測定義影響。","textEn":"Actual process windows also depend on resist, pattern and measurement definition."}],"quiz":{"question":"提高 NA 後哪項控制更重要？","questionEn":"What control becomes more demanding as NA increases?","options":["任意放寬表面起伏。","完全取消光阻厚度檢查。","焦距與晶圓高度控制。"],"optionsEn":["Freely allowing surface variation.","Removing resist-thickness checks.","Focus and wafer-height control."],"answer":2,"explanation":"焦距與晶圓高度控制。 固定其他因素時，焦深對 NA 的平方敏感。","explanationEn":"Focus and wafer-height control. With other factors fixed, focus depth scales inversely with NA squared."}},{"id":"a042-v7-04","order":4,"sequence":4,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-optics"],"prerequisiteIds":["a042-v7-03"],"title":"追蹤反射式 EUV 光路","titleEn":"Trace the reflective EUV optical path","objective":"理解光源到光阻的損耗介面。","objectiveEn":"Understand loss interfaces from source to resist.","instruction":"畫光源、照明鏡、光罩及投影鏡；在每次反射標能量流向；用假設反射率連乘比較損耗；說明為何使用真空。","instructionEn":"Draw source, illumination mirrors, mask and projection mirrors; mark energy flow at each reflection; multiply hypothetical reflectivities; explain the vacuum path.","observation":"多次反射的損耗會累積。","observationEn":"Losses accumulate across reflections.","failure":"勿以可見光玻璃透鏡取代 EUV 反射光學。","failureEn":"Do not substitute visible-light glass lenses for EUV reflective optics.","check":"光路圖包含真空邊界及逐段損耗。","checkEn":"Include vacuum boundaries and segment losses.","knowledge":[{"id":"a042-v7-04-k1","title":"原理與限制","titleEn":"Principle and limits","text":"EUV 易被材料吸收，因此系統採用反射鏡與真空。","textEn":"EUV absorption motivates mirrors and vacuum."},{"id":"a042-v7-04-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"單一元件的反射率不等於整機傳輸率。","textEn":"One mirror's reflectivity is not the system transmission."}],"quiz":{"question":"多面鏡的總傳輸如何估計？","questionEn":"How is transmission across mirrors estimated?","options":["在簡化模型中連乘各段傳輸率。","把百分比直接相加。","只看最後一面鏡。"],"optionsEn":["Multiply segment transmissions in a simplified model.","Add the percentages.","Use only the last mirror."],"answer":0,"explanation":"在簡化模型中連乘各段傳輸率。 EUV 易被材料吸收，因此系統採用反射鏡與真空。","explanationEn":"Multiply segment transmissions in a simplified model. EUV absorption motivates mirrors and vacuum."}},{"id":"a042-v7-05","order":5,"sequence":5,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-asml"],"prerequisiteIds":["a042-v7-04"],"title":"驗證非等倍率縮小","titleEn":"Verify anamorphic demagnification","objective":"把光罩座標正確轉到晶圓。","objectiveEn":"Map mask coordinates correctly to wafer coordinates.","instruction":"畫長方形光罩圖案；在兩軸分別用 4× 與 8× 縮小；計算四角座標；反算光罩尺寸以得到指定晶圓長寬。","instructionEn":"Draw a rectangular mask pattern; apply 4x and 8x demagnification on separate axes; calculate all corners; invert the mapping for a target wafer rectangle.","observation":"相同光罩邊長在兩方向產生不同晶圓尺寸。","observationEn":"Equal mask lengths produce different wafer lengths along the two axes.","failure":"如果成像比例錯，先核對軸定義而非旋轉圖形掩飾。","failureEn":"Check axis definitions rather than rotating a wrongly scaled image.","check":"正向與反向座標轉換互相一致。","checkEn":"Forward and inverse coordinate transforms agree.","knowledge":[{"id":"a042-v7-05-k1","title":"原理與限制","titleEn":"Principle and limits","text":"High-NA 光學採用兩方向不同縮小倍率。","textEn":"High-NA optics use unequal demagnification along two axes."},{"id":"a042-v7-05-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"非等倍率影響光罩資料、曝光場與接縫規劃。","textEn":"Anamorphic scaling affects mask data, exposure fields and stitching."}],"quiz":{"question":"同一光罩正方形必然成為晶圓正方形嗎？","questionEn":"Must a square mask feature remain square on the wafer?","options":["一定，只要使用 EUV。","不一定，兩軸倍率不同。","一定，倍率不影响形狀。"],"optionsEn":["Yes, whenever EUV is used.","No; the axis magnifications differ.","Yes; magnification cannot affect shape."],"answer":1,"explanation":"不一定，兩軸倍率不同。 High-NA 光學採用兩方向不同縮小倍率。","explanationEn":"No; the axis magnifications differ. High-NA optics use unequal demagnification along two axes."}},{"id":"a042-v7-06","order":6,"sequence":6,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-lab"],"prerequisiteIds":["a042-v7-05"],"title":"建立光學與製程責任界面","titleEn":"Define optical and process interfaces","objective":"避免把全部圖案問題歸給投影鏡。","objectiveEn":"Avoid assigning every pattern error to projection optics.","instruction":"列出光源、光罩、光阻與平台四介面；為各介面指定可觀測量；畫資料交接箭頭；給一個線寬偏差案例分配排查順序。","instructionEn":"List source, mask, resist and stage interfaces; assign observables; draw data handoffs; order checks for a linewidth-deviation case.","observation":"同樣的線寬偏差可來自多種因素。","observationEn":"Similar width errors can have several causes.","failure":"沒有隔離證據時，不把相關性寫成單一根因。","failureEn":"Without isolation evidence, do not state a single root cause.","check":"介面表含輸入、輸出及責任量測。","checkEn":"The interface table includes inputs, outputs and assigned measurements.","knowledge":[{"id":"a042-v7-06-k1","title":"原理與限制","titleEn":"Principle and limits","text":"成像品質由光學、材料及機電共同形成。","textEn":"Imaging quality emerges from optics, materials and mechatronics."},{"id":"a042-v7-06-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"跨設備資料必須使用可對應的位置與時間標記。","textEn":"Cross-tool data need matching spatial and time identifiers."}],"quiz":{"question":"圖案偏差可以僅憑照片判定鏡面故障嗎？","questionEn":"Can a pattern photo alone establish mirror failure?","options":["可以，光阻不影响圖案。","可以，所有誤差都源自光源。","不能，需分離其他介面因素。"],"optionsEn":["Yes; resist cannot affect patterns.","Yes; every error originates at the source.","No; other interface factors need isolation."],"answer":2,"explanation":"不能，需分離其他介面因素。 成像品質由光學、材料及機電共同形成。","explanationEn":"No; other interface factors need isolation. Imaging quality emerges from optics, materials and mechatronics."}}]},{"id":"a042-stage02","order":2,"title":"光罩、光阻與圖案轉移","titleEn":"Mask, resist and pattern transfer","description":"將光罩幾何與光阻、底層、蝕刻聯合判讀。","descriptionEn":"Interpret mask geometry together with resist, underlayers and etch.","steps":[{"id":"a042-v7-07","order":1,"sequence":7,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-process"],"prerequisiteIds":["a042-v7-06"],"title":"辨認光罩三維效應","titleEn":"Identify mask three-dimensional effects","objective":"區分平面設計與真實吸收層。","objectiveEn":"Distinguish layout from a physical absorber stack.","instruction":"畫反射多層膜與吸收層截面；加入斜入射光；比較兩個圖案方向；標記可能造成位置或最佳焦距差異的介面。","instructionEn":"Draw reflector and absorber sections; add oblique incidence; compare pattern orientations; mark interfaces that may shift position or best focus.","observation":"光罩不是沒有厚度的黑白投影片。","observationEn":"A mask is not a thickness-free black-and-white transparency.","failure":"若平面模型無法說明方向差異，列入三維光學效應。","failureEn":"Consider 3D optics when a planar model cannot explain orientation effects.","check":"說明一項平面模型遺漏的效應及驗證方法。","checkEn":"Explain one effect missing from a planar model and how to check it.","knowledge":[{"id":"a042-v7-07-k1","title":"原理與限制","titleEn":"Principle and limits","text":"吸收層與多層膜可改變相位及影像對比。","textEn":"Absorber and multilayer structures can affect phase and contrast."},{"id":"a042-v7-07-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"不同圖案方向可能需要分開評估。","textEn":"Different pattern orientations may need separate evaluation."}],"quiz":{"question":"為何需要光罩截面？","questionEn":"Why is a mask section needed?","options":["厚度與斜入射會影響成像。","光罩沒有任何反射。","平面尺寸永遠不重要。"],"optionsEn":["Thickness and oblique illumination affect imaging.","Masks have no reflection.","Planar dimensions never matter."],"answer":0,"explanation":"厚度與斜入射會影響成像。 吸收層與多層膜可改變相位及影像對比。","explanationEn":"Thickness and oblique illumination affect imaging. Absorber and multilayer structures can affect phase and contrast."}},{"id":"a042-v7-08","order":2,"sequence":8,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-ecosystem"],"prerequisiteIds":["a042-v7-07"],"title":"比較光罩補償前後輪廓","titleEn":"Compare compensated mask contours","objective":"理解光學鄰近修正的目的。","objectiveEn":"Understand the purpose of optical proximity correction.","instruction":"畫目標轉角與未補償成像輪廓；添加原創示意補償形狀；比較孤立線與密集線；標註仍須以模型及晶圓驗證。","instructionEn":"Draw target corners and uncorrected contours; add an original schematic compensation; compare isolated and dense lines; mark the need for model and wafer validation.","observation":"光罩形狀不必與最終圖案完全相同。","observationEn":"Mask shape need not duplicate the final pattern.","failure":"不要把手畫補償尺寸當成可製造光罩資料。","failureEn":"Do not treat hand-drawn compensation dimensions as mask-production data.","check":"示意圖清楚分開目標、光罩及預測影像。","checkEn":"Separate target, mask and predicted image.","knowledge":[{"id":"a042-v7-08-k1","title":"原理與限制","titleEn":"Principle and limits","text":"補償藉由改變輸入形狀改善印出的目標輪廓。","textEn":"Compensation changes input geometry to improve printed contours."},{"id":"a042-v7-08-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"同一補償可能受鄰近圖案及照明條件影響。","textEn":"Compensation depends on neighboring patterns and illumination."}],"quiz":{"question":"補償成功的判據是什麼？","questionEn":"What determines successful compensation?","options":["光罩看起來和目標完全相同。","晶圓輪廓更接近目標且視窗可接受。","只增加所有圖案面積。"],"optionsEn":["The mask looks identical to the target.","Wafer contours approach target within an acceptable window.","Every pattern area is enlarged."],"answer":1,"explanation":"晶圓輪廓更接近目標且視窗可接受。 補償藉由改變輸入形狀改善印出的目標輪廓。","explanationEn":"Wafer contours approach target within an acceptable window. Compensation changes input geometry to improve printed contours."}},{"id":"a042-v7-09","order":3,"sequence":9,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-process"],"prerequisiteIds":["a042-v7-08"],"title":"比較光阻厚度與倒塌風險","titleEn":"Compare resist thickness and collapse risk","objective":"用高寬比理解結構穩定。","objectiveEn":"Use aspect ratio to discuss feature stability.","instruction":"畫同寬不同高的三條光阻線；計算高度除以寬度；比較離焦與倒塌風險；列出薄化後圖案轉移的新要求。","instructionEn":"Draw equal-width resist lines at three heights; calculate height/width; compare focus and collapse concerns; list transfer demands after thinning.","observation":"較薄光阻可能有利成像但留下更少蝕刻餘量。","observationEn":"Thinner resist can help imaging while reducing etch margin.","failure":"若只追求低高寬比，補上後續轉移厚度預算。","failureEn":"Add transfer-thickness budgeting to aspect-ratio optimization.","check":"比較表含焦深、穩定與轉移三面向。","checkEn":"Compare focus depth, stability and transfer.","knowledge":[{"id":"a042-v7-09-k1","title":"原理與限制","titleEn":"Principle and limits","text":"高寬比把厚度與線寬連結到結構問題。","textEn":"Aspect ratio relates height and width to structural concerns."},{"id":"a042-v7-09-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"光阻最佳厚度須與底層及蝕刻共同設計。","textEn":"Resist thickness must be designed with underlayers and etch."}],"quiz":{"question":"光阻越薄是否必然越好？","questionEn":"Is thinner resist always better?","options":["是，蝕刻不需要任何遮罩。","是，薄膜不可能有缺陷。","否，還要滿足圖案轉移要求。"],"optionsEn":["Yes; etch needs no mask.","Yes; thin films cannot have defects.","No; pattern transfer must still work."],"answer":2,"explanation":"否，還要滿足圖案轉移要求。 高寬比把厚度與線寬連結到結構問題。","explanationEn":"No; pattern transfer must still work. Aspect ratio relates height and width to structural concerns."}},{"id":"a042-v7-10","order":4,"sequence":10,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-ecosystem"],"prerequisiteIds":["a042-v7-09"],"title":"建立光阻與底層介面圖","titleEn":"Map the resist-underlayer interface","objective":"把黏附、形貌與轉移一起審查。","objectiveEn":"Review adhesion, morphology and transfer together.","instruction":"畫光阻、底層與目標膜；標示各層作用；比較兩種假設底層造成的線形差異；規劃只改底層的對照組。","instructionEn":"Draw resist, underlayer and target film; label roles; compare hypothetical line-shape changes for two underlayers; design an underlayer-only control.","observation":"相同光阻不保證在不同底層有相同結果。","observationEn":"The same resist need not behave identically on different underlayers.","failure":"同時換光阻與底層會混淆原因，拆成實驗矩陣。","failureEn":"Separate simultaneous resist and underlayer changes into a matrix.","check":"每層有功能、關鍵介面與觀察項。","checkEn":"Each layer has a function, interface and observable.","knowledge":[{"id":"a042-v7-10-k1","title":"原理與限制","titleEn":"Principle and limits","text":"光阻與底層需共同最佳化。","textEn":"Resist and underlayer require co-optimization."},{"id":"a042-v7-10-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"單一材料排名不能取代堆疊整合驗證。","textEn":"A material ranking cannot replace stack-integration verification."}],"quiz":{"question":"如何先辨認底層影響？","questionEn":"How can underlayer effects first be isolated?","options":["固定光阻及其他條件比較底層。","同時更改所有堆疊。","只比較材料商品名稱。"],"optionsEn":["Hold resist and other conditions fixed.","Change every layer at once.","Compare product names only."],"answer":0,"explanation":"固定光阻及其他條件比較底層。 光阻與底層需共同最佳化。","explanationEn":"Hold resist and other conditions fixed. Resist and underlayer require co-optimization."}},{"id":"a042-v7-11","order":5,"sequence":11,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-ecosystem"],"prerequisiteIds":["a042-v7-10"],"title":"區分光子與材料隨機性","titleEn":"Distinguish photon and material stochasticity","objective":"理解少數缺陷與平均線寬的差異。","objectiveEn":"Distinguish rare defects from average linewidth.","instruction":"畫相同目標的二十個接觸孔；加入自訂缺孔與尺寸擾動；分別統計平均尺寸及缺孔數；比較兩批平均相同的資料。","instructionEn":"Draw twenty target contacts; add hypothetical missing holes and size variations; count mean size and missing holes separately; compare batches with equal means.","observation":"平均尺寸一致仍可能有不同失敗率。","observationEn":"Equal mean size can coexist with different failure rates.","failure":"不要以二十個樣本推估量產極低缺陷率；註明樣本限制。","failureEn":"Do not infer production-scale rare-event rates from twenty samples.","check":"同時報告平均、散布、缺陷數與樣本數。","checkEn":"Report mean, spread, defect count and sample size.","knowledge":[{"id":"a042-v7-11-k1","title":"原理與限制","titleEn":"Principle and limits","text":"隨機缺陷需用分布及事件數評估。","textEn":"Stochastic defects require distributions and event counts."},{"id":"a042-v7-11-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"看不到缺陷不等於缺陷機率為零。","textEn":"Observing no defects does not establish zero probability."}],"quiz":{"question":"平均線寬正常就可排除缺孔嗎？","questionEn":"Does a normal mean linewidth rule out missing holes?","options":["可以，平均值涵蓋所有拓撲。","不能，需單獨檢查缺陷事件。","可以，只需增加影像亮度。"],"optionsEn":["Yes; a mean captures all topology.","No; defect events need separate inspection.","Yes; just brighten the image."],"answer":1,"explanation":"不能，需單獨檢查缺陷事件。 隨機缺陷需用分布及事件數評估。","explanationEn":"No; defect events need separate inspection. Stochastic defects require distributions and event counts."}},{"id":"a042-v7-12","order":6,"sequence":12,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-process"],"prerequisiteIds":["a042-v7-11"],"title":"追蹤顯影到蝕刻的圖案變化","titleEn":"Track patterns from development to etch","objective":"避免只用光阻圖案評估最終結構。","objectiveEn":"Avoid assessing final structures from resist alone.","instruction":"畫顯影後、硬遮罩後與目標膜後三個輪廓；逐站標線寬變化；比較斜壁與頂視影像；分配每站允許的教學誤差預算。","instructionEn":"Draw post-develop, hard-mask and target-film contours; mark width changes; compare sloped walls with top views; allocate hypothetical error budgets by stage.","observation":"頂視線寬相同可對應不同側壁。","observationEn":"Equal top-view widths can hide different sidewalls.","failure":"未取得蝕刻後證據時，結論只限光阻階段。","failureEn":"Without after-etch evidence, limit conclusions to the resist stage.","check":"三站輪廓與每次轉移偏差可對應。","checkEn":"Match three contours and transfer deviations.","knowledge":[{"id":"a042-v7-12-k1","title":"原理與限制","titleEn":"Principle and limits","text":"最終圖案是曝光、顯影與轉移共同結果。","textEn":"The final pattern combines exposure, development and transfer."},{"id":"a042-v7-12-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"每次轉移可能改變尺寸與形貌。","textEn":"Each transfer can change dimensions and morphology."}],"quiz":{"question":"光阻照片能否保證目標膜形貌？","questionEn":"Can a resist photo guarantee target-film geometry?","options":["能，所有層必定等比例複製。","能，只要曝光一次。","不能，需蝕刻後量測。"],"optionsEn":["Yes; every layer replicates perfectly.","Yes, after a single exposure.","No; after-etch metrology is needed."],"answer":2,"explanation":"不能，需蝕刻後量測。 最終圖案是曝光、顯影與轉移共同結果。","explanationEn":"No; after-etch metrology is needed. The final pattern combines exposure, development and transfer."}}]},{"id":"a042-stage03","order":3,"title":"平台、焦距與曝光場","titleEn":"Stages, focus and exposure fields","description":"建立定位、場接縫與時間預算。","descriptionEn":"Build positioning, stitching and timing budgets.","steps":[{"id":"a042-v7-13","order":1,"sequence":13,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-motion"],"prerequisiteIds":["a042-v7-12"],"title":"推演晶圓與光罩同步掃描","titleEn":"Model synchronized wafer and mask scanning","objective":"建立兩平台相對運動的概念。","objectiveEn":"Model relative motion of both stages.","instruction":"畫曝光狹縫與兩平台；指定示意縮小倍率；推演對應位移；加入一段速度誤差並標記其影像方向。","instructionEn":"Draw an exposure slit and both stages; choose a schematic demagnification; derive corresponding displacements; add a velocity error and mark its image direction.","observation":"平台各自位置正確仍須保持相對同步。","observationEn":"Individually correct positions still require relative synchronization.","failure":"若兩平台使用相同位移卻倍率不同，重算對應關係。","failureEn":"Recalculate mapping if both stages move equally despite demagnification.","check":"時間圖顯示兩平台與相對誤差。","checkEn":"A time plot shows both stages and relative error.","knowledge":[{"id":"a042-v7-13-k1","title":"原理與限制","titleEn":"Principle and limits","text":"掃描成像需要平台運動與光學倍率一致。","textEn":"Scanning requires motion consistent with optical scaling."},{"id":"a042-v7-13-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"同步誤差需按曝光時刻評估。","textEn":"Synchronization error must be evaluated during exposure."}],"quiz":{"question":"只檢查平台終點位置足夠嗎？","questionEn":"Is checking only final stage position enough?","options":["不夠，曝光期間同步也重要。","足夠，中途軌跡不影響影像。","足夠，兩平台不需配合。"],"optionsEn":["No; synchronization during exposure matters.","Yes; the intermediate path cannot affect imaging.","Yes; stages need no coordination."],"answer":0,"explanation":"不夠，曝光期間同步也重要。 掃描成像需要平台運動與光學倍率一致。","explanationEn":"No; synchronization during exposure matters. Scanning requires motion consistent with optical scaling."}},{"id":"a042-v7-14","order":2,"sequence":14,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-asml","v7-highna-ecosystem"],"prerequisiteIds":["a042-v7-13"],"title":"規劃半曝光場拼接","titleEn":"Plan half-field stitching","objective":"辨認接縫處的對準與連接問題。","objectiveEn":"Identify alignment and continuity at field seams.","instruction":"把示意晶片切成兩個場；畫一條跨接縫導線；分別加入平移與縮放偏差；比較開路、短路及重疊情境。","instructionEn":"Split a schematic die into two fields; draw a crossing line; add translation and scaling errors separately; compare open, short and overlap cases.","observation":"接縫不是把兩張圖靠近就完成。","observationEn":"Stitching is more than placing images side by side.","failure":"不要假設每個晶片都需拼接；先比較晶片與曝光場大小。","failureEn":"Compare die and field sizes before assuming stitching is required.","check":"說明何時需要拼接及如何檢查邊界。","checkEn":"Explain when stitching is needed and how boundaries are checked.","knowledge":[{"id":"a042-v7-14-k1","title":"原理與限制","titleEn":"Principle and limits","text":"非等倍率使曝光場規劃改變。","textEn":"Anamorphic optics change exposure-field planning."},{"id":"a042-v7-14-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"跨場圖案需額外檢查位置與連續性。","textEn":"Cross-field patterns need alignment and continuity checks."}],"quiz":{"question":"所有晶片一定需兩場拼接嗎？","questionEn":"Must every die use two stitched fields?","options":["一定，與晶片大小無關。","不一定，取決於晶片與場的尺寸。","不必，接縫永遠沒有誤差。"],"optionsEn":["Yes, regardless of die size.","No; it depends on die and field size.","No, because seams can never have errors."],"answer":1,"explanation":"不一定，取決於晶片與場的尺寸。 非等倍率使曝光場規劃改變。","explanationEn":"No; it depends on die and field size. Anamorphic optics change exposure-field planning."}},{"id":"a042-v7-15","order":3,"sequence":15,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-metrology"],"prerequisiteIds":["a042-v7-14"],"title":"建立晶圓高度與焦距圖","titleEn":"Build a wafer-height and focus map","objective":"把形貌轉為可校正的誤差。","objectiveEn":"Translate topography into correctable errors.","instruction":"畫九點高度圖；扣除整體傾斜平面；將殘差與假設焦深範圍比較；標記需重測或限制曝光的位置。","instructionEn":"Draw a nine-point height map; subtract a best-fit tilt plane; compare residuals with a hypothetical focus range; flag sites for remeasurement or exposure limits.","observation":"平面傾斜校正後仍可能有局部起伏。","observationEn":"Local topography can remain after tilt correction.","failure":"若只用中心點對焦，增加邊緣與局部高點取樣。","failureEn":"Add edge and local-high sampling to center-only focusing.","check":"原始高度、校正量與殘差均有紀錄。","checkEn":"Record raw heights, corrections and residuals.","knowledge":[{"id":"a042-v7-15-k1","title":"原理與限制","titleEn":"Principle and limits","text":"焦距控制依賴可追溯的高度量測。","textEn":"Focus control depends on traceable height measurements."},{"id":"a042-v7-15-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"校正模型的自由度有限，不能消除所有形貌。","textEn":"A correction model has finite freedom and cannot erase all topography."}],"quiz":{"question":"扣除傾斜後還應看什麼？","questionEn":"What remains to inspect after removing tilt?","options":["只看全片平均高度。","刪除不符合平面的數據。","局部殘差是否超出焦距容忍。"],"optionsEn":["Only mean wafer height.","Delete data not fitting the plane.","Whether local residuals exceed focus tolerance."],"answer":2,"explanation":"局部殘差是否超出焦距容忍。 焦距控制依賴可追溯的高度量測。","explanationEn":"Whether local residuals exceed focus tolerance. Focus control depends on traceable height measurements."}},{"id":"a042-v7-16","order":4,"sequence":16,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-motion"],"prerequisiteIds":["a042-v7-15"],"title":"比較熱漂移與隨機振動","titleEn":"Compare thermal drift and random vibration","objective":"按時間尺度分類位置誤差。","objectiveEn":"Classify positioning error by time scale.","instruction":"畫緩慢漂移及快速擾動兩條假設訊號；選不同取樣間隔；比較可觀測成分；為兩類問題分別指定溫度或位置證據。","instructionEn":"Draw slow drift and fast disturbance signals; choose sampling intervals; compare observable components; assign temperature or position evidence to each.","observation":"相同誤差幅度不一定需要相同校正。","observationEn":"Equal error amplitudes can require different corrections.","failure":"過慢取樣可能漏掉快速擾動；保留量測頻寬。","failureEn":"Slow sampling can miss fast disturbances; retain bandwidth information.","check":"分類含時間尺度、感測量與修正假說。","checkEn":"Classify time scale, sensing quantity and correction hypothesis.","knowledge":[{"id":"a042-v7-16-k1","title":"原理與限制","titleEn":"Principle and limits","text":"機電精度同時受環境與運動狀態影響。","textEn":"Mechatronic precision depends on environment and motion."},{"id":"a042-v7-16-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"量測頻率必須適合欲觀察的變化。","textEn":"Sampling must suit the changes being observed."}],"quiz":{"question":"慢速溫度紀錄能否排除快速振動？","questionEn":"Can slow temperature logging exclude fast vibration?","options":["不能，需適當頻寬的位置量測。","能，所有誤差都有同一頻率。","能，只要平均溫度固定。"],"optionsEn":["No; position measurement with suitable bandwidth is needed.","Yes; all errors share one frequency.","Yes, if average temperature is fixed."],"answer":0,"explanation":"不能，需適當頻寬的位置量測。 機電精度同時受環境與運動狀態影響。","explanationEn":"No; position measurement with suitable bandwidth is needed. Mechatronic precision depends on environment and motion."}},{"id":"a042-v7-17","order":5,"sequence":17,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-asml"],"prerequisiteIds":["a042-v7-16"],"title":"拆解曝光時間與產能","titleEn":"Decompose exposure time and throughput","objective":"避免以曝光次數直接判定總產能。","objectiveEn":"Avoid deriving total throughput from exposure count alone.","instruction":"列出對準、移動、曝光與換片時間；建立兩種假設排程；分別增加場數及縮短平台時間；比較總時間及瓶頸。","instructionEn":"List alignment, motion, exposure and exchange times; create two hypothetical schedules; vary field count and stage time separately; compare totals and bottlenecks.","observation":"場數增加不等於總時間必然成同比例增加。","observationEn":"More fields do not force total time to increase proportionally.","failure":"不要用公開峰值代替實際光阻劑量與排程條件。","failureEn":"Do not substitute peak claims for dose and scheduling conditions.","check":"以同條件時間帳本比較方案。","checkEn":"Compare schemes using a timing ledger under matching conditions.","knowledge":[{"id":"a042-v7-17-k1","title":"原理與限制","titleEn":"Principle and limits","text":"產能由多個時間項及重疊作業共同決定。","textEn":"Throughput depends on several time terms and overlap."},{"id":"a042-v7-17-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"劑量、場數與平台速度的取捨需共同審查。","textEn":"Dose, field count and stage speed require joint review."}],"quiz":{"question":"半場是否必然使每片時間加倍？","questionEn":"Does a half field necessarily double wafer time?","options":["必然，其他動作時間為零。","不必然，要看完整時間預算。","完全不影响任何時間項。"],"optionsEn":["Yes; all other actions take zero time.","Not necessarily; inspect the full timing budget.","It cannot affect any time term."],"answer":1,"explanation":"不必然，要看完整時間預算。 產能由多個時間項及重疊作業共同決定。","explanationEn":"Not necessarily; inspect the full timing budget. Throughput depends on several time terms and overlap."}},{"id":"a042-v7-18","order":6,"sequence":18,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-metrology"],"prerequisiteIds":["a042-v7-17"],"title":"追蹤曝光場內的劑量分布","titleEn":"Track dose distribution within a field","objective":"區分平均能量與局部曝光均勻性。","objectiveEn":"Separate average energy from local exposure uniformity.","instruction":"畫中心與兩側三區曝光圖；指定相同平均但不同分布的假設劑量；比較每區線寬回應；列出感測器位置及校正證據。","instructionEn":"Draw center and two edge exposure zones; assign equal-average but differently distributed hypothetical doses; compare local linewidth responses; list sensor positions and calibration evidence.","observation":"平均曝光量相同仍可能有場內差異。","observationEn":"Equal average exposure can conceal within-field differences.","failure":"若只看總能量，補上位置分布，避免把光阻差異全部歸因於光源。","failureEn":"Add spatial distribution to total energy and avoid attributing every resist difference to the source.","check":"交出每區劑量、觀察及可能混淆因素。","checkEn":"Report dose, observation and potential confounders by zone.","knowledge":[{"id":"a042-v7-18-k1","title":"原理與限制","titleEn":"Principle and limits","text":"曝光品質包含空間與時間的均勻性。","textEn":"Exposure quality includes spatial and temporal uniformity."},{"id":"a042-v7-18-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"量測點的覆蓋範圍會限制對全場的結論。","textEn":"Measurement coverage limits conclusions about the whole field."}],"quiz":{"question":"平均劑量相同是否證明全場曝光一致？","questionEn":"Does equal average dose prove uniform field exposure?","options":["是，平均值等於每個點。","是，場邊永遠沒有誤差。","否，還需檢查空間分布。"],"optionsEn":["Yes; the average equals every point.","Yes; field edges never have errors.","No; inspect spatial distribution."],"answer":2,"explanation":"否，還需檢查空間分布。 曝光品質包含空間與時間的均勻性。","explanationEn":"No; inspect spatial distribution. Exposure quality includes spatial and temporal uniformity."}}]},{"id":"a042-stage04","order":4,"title":"量測、缺陷與整合驗證","titleEn":"Metrology, defects and integrated verification","description":"把影像、製程視窗與電性測試連接成證據鏈。","descriptionEn":"Connect images, process windows and electrical tests into an evidence chain.","steps":[{"id":"a042-v7-19","order":1,"sequence":19,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-ecosystem"],"prerequisiteIds":["a042-v7-18"],"title":"建立焦距與劑量矩陣","titleEn":"Build a focus-exposure matrix","objective":"以多條件找可接受製程區域。","objectiveEn":"Find acceptable regions across conditions.","instruction":"畫三個焦距×三個相對劑量的假設矩陣；填入示意線寬及缺陷觀察；圈出同時符合兩條件的區域；標明數值不供設備設定。","instructionEn":"Draw a hypothetical three-focus by three-relative-dose matrix; enter illustrative widths and defects; outline the region meeting both conditions; label values as non-operational.","observation":"單一最佳點不代表有寬廣製程視窗。","observationEn":"One optimum point does not establish a broad process window.","failure":"若只選線寬最接近的一格，加入缺陷與鄰近格穩定性。","failureEn":"Add defects and neighboring-condition stability to closest-width selection.","check":"判定使用至少兩項品質指標。","checkEn":"Use at least two quality criteria.","knowledge":[{"id":"a042-v7-19-k1","title":"原理與限制","titleEn":"Principle and limits","text":"製程視窗是同時滿足條件的範圍。","textEn":"A process window is a range satisfying joint conditions."},{"id":"a042-v7-19-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"裕量比單次最佳結果更有助於穩定性判讀。","textEn":"Margin is more informative about robustness than one optimum result."}],"quiz":{"question":"只有一格合格代表什麼？","questionEn":"What does only one passing matrix cell indicate?","options":["可能視窗狹窄，需更多驗證。","已證明任何條件都穩定。","可刪除所有失敗格。"],"optionsEn":["A potentially narrow window needing more checks.","Stability under every condition is proven.","All failing cells may be removed."],"answer":0,"explanation":"可能視窗狹窄，需更多驗證。 製程視窗是同時滿足條件的範圍。","explanationEn":"A potentially narrow window needing more checks. A process window is a range satisfying joint conditions."}},{"id":"a042-v7-20","order":2,"sequence":20,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-metrology"],"prerequisiteIds":["a042-v7-19"],"title":"分辨 CD、疊對與邊緣位置","titleEn":"Separate CD, overlay and edge placement","objective":"避免不同誤差指標互相替代。","objectiveEn":"Avoid substituting one error metric for another.","instruction":"畫上下兩層線路；分別改變寬度與平移；量出 CD、層間偏移與目標邊緣差；比較兩項誤差相加的情況。","instructionEn":"Draw lines on two layers; vary width and translation separately; measure CD, layer offset and target-edge difference; compare combined errors.","observation":"CD 合格仍可能因疊對偏差造成連接失敗。","observationEn":"Passing CD can coexist with failed connections from overlay error.","failure":"若只報單一「精度」，指定其物理定義與位置。","failureEn":"Replace a generic accuracy number with a physical definition and location.","check":"三種指標各有圖示與量測基準。","checkEn":"Illustrate all three metrics with measurement references.","knowledge":[{"id":"a042-v7-20-k1","title":"原理與限制","titleEn":"Principle and limits","text":"尺寸與位置是不同的品質維度。","textEn":"Size and position are distinct quality dimensions."},{"id":"a042-v7-20-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"邊緣位置可能同時受尺寸與疊對影響。","textEn":"Edge position can reflect both size and overlay."}],"quiz":{"question":"CD 合格能否證明層間對準？","questionEn":"Does passing CD prove interlayer alignment?","options":["能，寬度就是位置。","不能，疊對需另測。","能，只要線條發亮。"],"optionsEn":["Yes; width is position.","No; overlay requires separate measurement.","Yes, if lines appear bright."],"answer":1,"explanation":"不能，疊對需另測。 尺寸與位置是不同的品質維度。","explanationEn":"No; overlay requires separate measurement. Size and position are distinct quality dimensions."}},{"id":"a042-v7-21","order":3,"sequence":21,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-metrology"],"prerequisiteIds":["a042-v7-20"],"title":"規劃光學與電子束互補檢查","titleEn":"Plan complementary optical and e-beam checks","objective":"匹配檢查速度與缺陷解析度。","objectiveEn":"Match inspection speed and defect resolution.","instruction":"列出全片趨勢與局部缺陷兩類問題；為各類選量測工具；設計熱點加隨機位置取樣；比較只查熱點會漏掉的情況。","instructionEn":"Separate whole-wafer trends from local defects; assign tools; sample hotspots plus random sites; compare what hotspot-only inspection could miss.","observation":"快速取樣與高解析檢查需互相補充。","observationEn":"Fast sampling and high-resolution inspection complement each other.","failure":"不宣稱取樣等於全片每一結構檢查。","failureEn":"Do not equate sampling with inspection of every structure.","check":"計畫列出覆蓋範圍、解析能力與未覆蓋區。","checkEn":"State coverage, resolving capability and gaps.","knowledge":[{"id":"a042-v7-21-k1","title":"原理與限制","titleEn":"Principle and limits","text":"光學量測與電子束檢查具有不同速度與資訊特性。","textEn":"Optical metrology and e-beam inspection differ in speed and information."},{"id":"a042-v7-21-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"取樣策略會影響可發現的缺陷種類。","textEn":"Sampling strategy changes the defects likely to be found."}],"quiz":{"question":"只檢查已知熱點有何限制？","questionEn":"What limits hotspot-only inspection?","options":["能保證沒有任何缺陷。","使儀器解析度無限大。","可能漏掉未知位置的缺陷。"],"optionsEn":["It guarantees no defects anywhere.","It gives infinite resolution.","It may miss defects in unexpected locations."],"answer":2,"explanation":"可能漏掉未知位置的缺陷。 光學量測與電子束檢查具有不同速度與資訊特性。","explanationEn":"It may miss defects in unexpected locations. Optical metrology and e-beam inspection differ in speed and information."}},{"id":"a042-v7-22","order":4,"sequence":22,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-ecosystem"],"prerequisiteIds":["a042-v7-21"],"title":"建立缺陷分類與電性對照","titleEn":"Classify defects against electrical outcomes","objective":"把影像異常轉成可驗證的功能假說。","objectiveEn":"Translate image anomalies into testable functional hypotheses.","instruction":"畫橋接、缺孔及線頸三種原創示意；預測短路、開路或高阻；配對假設電性結果；列出影像不足以判斷的案例。","instructionEn":"Draw original bridge, missing-contact and necking examples; predict short, open or high resistance; pair hypothetical electrical results; list cases images cannot resolve.","observation":"可見形貌與電性失敗需建立對照。","observationEn":"Visible morphology and electrical failure need correlation.","failure":"不要將每個影像雜點都標成失效；先查成像與樣品條件。","failureEn":"Check imaging and sample conditions before treating every speck as a defect.","check":"分類表包含形貌、功能假說與追加證據。","checkEn":"Include morphology, functional hypothesis and additional evidence.","knowledge":[{"id":"a042-v7-22-k1","title":"原理與限制","titleEn":"Principle and limits","text":"缺陷的功能影響取決於位置及連接關係。","textEn":"Functional impact depends on location and connectivity."},{"id":"a042-v7-22-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"影像分類須與其他證據交叉確認。","textEn":"Image classification needs cross-checks."}],"quiz":{"question":"一個雜點能直接證明短路嗎？","questionEn":"Does a speck directly prove a short?","options":["不能，需確認形貌與電性。","能，任何雜點都導電。","能，影像不可能有雜訊。"],"optionsEn":["No; morphology and electrical evidence are needed.","Yes; every speck conducts.","Yes; images cannot contain noise."],"answer":0,"explanation":"不能，需確認形貌與電性。 缺陷的功能影響取決於位置及連接關係。","explanationEn":"No; morphology and electrical evidence are needed. Functional impact depends on location and connectivity."}},{"id":"a042-v7-23","order":5,"sequence":23,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-asml","v7-highna-lab"],"prerequisiteIds":["a042-v7-22"],"title":"比較 DUV、多重圖案化與 High NA","titleEn":"Compare DUV, multipatterning and High NA","objective":"依圖層需求選擇方法而非技術排名。","objectiveEn":"Select methods by layer requirements rather than prestige.","instruction":"為三種示意圖層列出節距、場大小及產能需求；比較單次與多次圖案化的步驟；標出疊對及成本項；說明一個不需 High NA 的案例。","instructionEn":"Specify pitch, field size and throughput for three illustrative layers; compare single and multiple patterning; mark overlay and cost terms; explain a layer not requiring High NA.","observation":"不同圖層可使用不同微影策略。","observationEn":"Different layers can use different lithography strategies.","failure":"不能把所有舊設備視為失效；先看需求匹配。","failureEn":"Match requirements before treating older tools as unsuitable.","check":"選擇表有需求、收益、限制與衍生課程。","checkEn":"The selection table includes needs, benefits, limits and related study.","knowledge":[{"id":"a042-v7-23-k1","title":"原理與限制","titleEn":"Principle and limits","text":"製程選擇需整合解析度、成本與圖案轉移。","textEn":"Process selection integrates resolution, cost and transfer."},{"id":"a042-v7-23-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"更高 NA 不自動成為每層的最佳選項。","textEn":"Higher NA is not automatically best for every layer."}],"quiz":{"question":"哪種比較最合理？","questionEn":"Which comparison is most useful?","options":["單純依設備新舊排名。","在同一圖層需求下比較完整流程。","只看最小公開線寬。"],"optionsEn":["Rank solely by equipment age.","Compare complete flows for the same layer requirements.","Use only minimum advertised linewidth."],"answer":1,"explanation":"在同一圖層需求下比較完整流程。 製程選擇需整合解析度、成本與圖案轉移。","explanationEn":"Compare complete flows for the same layer requirements. Process selection integrates resolution, cost and transfer."}},{"id":"a042-v7-24","order":6,"sequence":24,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-highna-lab","v7-highna-metrology"],"prerequisiteIds":["a042-v7-23"],"title":"完成成像整合交付","titleEn":"Complete the imaging-integration dossier","objective":"用完整證據支持下一輪試驗。","objectiveEn":"Support the next experiment with complete evidence.","instruction":"收集尺度表、焦距矩陣與缺陷分類；標記每張圖是自繪、假設或實測來源；列出三個未解問題；提出優先驗證的介面。","instructionEn":"Collect scale definitions, focus matrix and defect classification; label original, hypothetical and sourced evidence; list three unresolved questions; prioritize an interface for verification.","observation":"漂亮影像不能取代統計與流程相容證據。","observationEn":"Attractive images cannot replace statistics and integration evidence.","failure":"缺乏電性或轉移結果時，限制結論到已驗證階段。","failureEn":"Limit conclusions to verified stages when electrical or transfer evidence is absent.","check":"交付包含可重現假設、資料對應與下一步。","checkEn":"Deliver reproducible assumptions, data mapping and a next step.","knowledge":[{"id":"a042-v7-24-k1","title":"原理與限制","titleEn":"Principle and limits","text":"整合成熟度需要多種證據互相支持。","textEn":"Integration maturity requires mutually supporting evidence."},{"id":"a042-v7-24-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"本課程是成像原理審查，不是光刻機建造藍圖。","textEn":"This course reviews imaging principles, not lithography-machine construction blueprints."}],"quiz":{"question":"哪項最能支持總工程師決策？","questionEn":"What best supports a chief engineer's decision?","options":["只展示單張最佳照片。","宣稱公開原理等於完整量產配方。","可追溯的視窗、缺陷與未知項。"],"optionsEn":["Show only one best photograph.","Claim public principles are a complete production recipe.","Traceable windows, defects and unknowns."],"answer":2,"explanation":"可追溯的視窗、缺陷與未知項。 整合成熟度需要多種證據互相支持。","explanationEn":"Traceable windows, defects and unknowns. Integration maturity requires mutually supporting evidence."}}]}],"curriculumVersion":7,"subcategory":"lithography","subcategoryTitle":"光阻、光罩與微影","subcategoryTitleEn":"Resists, masks and lithography"}};
